import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Contracts 1.7.0 — Accept Evidence Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts 1.7.0 — Accept Evidence Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/contracts-1-7-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts 1.7.0 — Accept Evidence Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/contracts-1-7-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/contracts-1-7-0-production-readiness.md","filePath":"deployment/contracts-1-7-0-production-readiness.md","lastUpdated":1790351585000}'),r={name:"deployment/contracts-1-7-0-production-readiness.md"};function n(s,t,i,c,l,g){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="contracts-1-7-0-—-accept-evidence-production-readiness-audit" tabindex="-1">Contracts 1.7.0 — Accept Evidence Production Readiness Audit <a class="header-anchor" href="#contracts-1-7-0-—-accept-evidence-production-readiness-audit" aria-label="Permalink to &quot;Contracts 1.7.0 — Accept Evidence Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-24</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — migrate + SPA; signature/ID toggles hard-gated on Storage</td></tr><tr><td><strong>Scope</strong></td><td>Tenant Contracts module <code>contracts</code> <strong>1.6.0 → 1.7.0</strong> (optional phone / signature image / ID document on public accept)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./contracts">Contracts production</a> · <a href="./contracts-production-readiness">1.1.0 readiness</a> · <a href="./storage-production-readiness">Storage readiness</a> · <a href="/developer-guide/contracts">Developer</a> · <a href="/user-guide/contracts">User</a> · <a href="/api/tenant-v1-contracts">API</a> · <a href="/user-guide/tenant-settings">Tenant settings</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><p>Additive MINOR on the existing contracts module. No new permissions, queues, scheduler entries, or env vars. Evidence toggles default <strong>off</strong> — workspaces that never change Settings keep the 1.5.0 name/email/IP accept path.</p><p>This audit is <strong>Contracts 1.7.0 accept evidence only</strong>. Prior Contracts readiness pages remain valid for their scopes.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Public contract accept (<code>/#/accept/contracts/{token}</code>) can require <strong>phone</strong>, a <strong>drawn or uploaded signature image</strong>, and/or a <strong>national ID / passport / other</strong> upload. Each requirement is an independent Settings → General boolean. Signatures and ID files store on the private uploads disk under tenant-scoped paths; staff download via authenticated <code>contracts.view</code> endpoints (timeline-audited). IP and user agent are always recorded on accept. Accepted contracts embed signer metadata and the signature image on the branded PDF (ID files remain download-only).</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog <code>1.7.0</code> migrate-only (no <code>db:seed</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Evidence columns additive + nullable</td><td><strong>Pass</strong></td></tr><tr><td>Settings toggles default off</td><td><strong>Pass</strong></td></tr><tr><td>Public accept throttle <code>contract-acceptance</code></td><td><strong>Pass</strong></td></tr><tr><td>Token hashed; cleared on accept / terminate</td><td><strong>Pass</strong></td></tr><tr><td>Uploads private disk; paths omitted from list/show JSON</td><td><strong>Pass</strong></td></tr><tr><td>Staff downloads gated <code>module:contracts</code> + <code>can:contracts.view</code></td><td><strong>Pass</strong></td></tr><tr><td>Workspace upload validation (size/MIME) via <code>ValidatesWorkspaceUploads</code></td><td><strong>Pass</strong></td></tr><tr><td>Storage entitlement required to enable signature/ID settings (API + SPA)</td><td><strong>Pass</strong></td></tr><tr><td>Orphan files cleaned if accept txn fails after <code>store()</code></td><td><strong>Pass</strong></td></tr><tr><td>Force-delete purges signature/ID files; soft-delete retains</td><td><strong>Pass</strong></td></tr><tr><td>Download audit on contract timeline</td><td><strong>Pass</strong></td></tr><tr><td>PDF embeds signature image + acceptance block</td><td><strong>Pass</strong></td></tr><tr><td>Empty stub migration <code>2026_09_23_210611_…</code></td><td><strong>Pass</strong> — not shipped</td></tr><tr><td>Pest <code>ContractAcceptanceTest</code></td><td><strong>Pass</strong></td></tr><tr><td>Playwright <code>e2e/tests/contracts</code></td><td><strong>Pass</strong></td></tr><tr><td>Docs + upgrade + this page</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI and <code>php artisan migrate --force</code> <strong>before</strong> the SPA that posts evidence multipart / Settings toggles.</p><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>F1</td><td>High</td><td><strong>Fixed</strong></td><td>Empty stub migration duplicated evidence filename intent</td><td>Deleted; only <code>2026_09_24_020619_…</code> ships</td></tr><tr><td>F2</td><td>Medium</td><td><strong>Fixed</strong></td><td>Settings allowed signature/ID without Storage</td><td>API rejects enabling those keys without Storage; SPA disables switches + copy</td></tr><tr><td>F3</td><td>Low</td><td><strong>Fixed</strong></td><td>Orphan private files if accept txn failed after store</td><td>Track paths and delete in <code>finally</code> when txn does not commit</td></tr><tr><td>F4</td><td>Medium</td><td><strong>Fixed</strong></td><td>ID/signature PII had no purge or download audit</td><td>Force-delete purges files; soft-delete retains; downloads record <code>acceptance_evidence_downloaded</code></td></tr><tr><td>F5</td><td>Low</td><td><strong>Fixed</strong></td><td>PDF lacked signature image</td><td>Acceptance block + signature data URI on PDF; ID stays download-only</td></tr><tr><td>F6</td><td>Low</td><td><strong>Fixed</strong></td><td>Ops docs lagged version / upgrade / readiness</td><td>This page + contracts ops + <a href="/deployment/upgrade">Upgrade</a></td></tr></tbody></table><h3 id="accepted-intentional" tabindex="-1">Accepted / intentional <a class="header-anchor" href="#accepted-intentional" aria-label="Permalink to &quot;Accepted / intentional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>No new permissions</td><td>Reuse <code>contracts.view</code> for downloads; public accept remains token-gated</td></tr><tr><td>Defaults off</td><td>Phone / signature / ID requirements are opt-in per workspace</td></tr><tr><td>ID not embedded in PDF</td><td>Full ID images stay on authenticated download only</td></tr><tr><td>Soft-delete keeps evidence</td><td>Restore must recover files; permanent delete is the purge boundary</td></tr><tr><td>Quotation accept parity</td><td>Only URL/<code>workspace=</code> tenancy fix; quotation does not gain evidence fields</td></tr><tr><td>Catalog bump ≠ auto-install</td><td>Workspaces that never entitled Contracts are unchanged</td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/Contract/ContractAcceptanceTest.php</code></td><td>Required green</td><td>Link issue, basic accept, expired token, email link, terminate clears token, PDF, evidence + downloads + purge + Storage settings gate</td></tr><tr><td><code>npm run test:e2e:contracts</code></td><td>Required green</td><td>Workflow activate + <code>contracts.accept-evidence</code></td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Companion <strong>CI</strong> green (Backend / Frontend / Docs)</li><li><strong>Backend</strong> — <code>php artisan migrate --force</code> (<code>2026_09_24_020619_add_contract_acceptance_evidence_fields_to_contracts_table</code> + catalog bump <code>1.7.0</code>)</li><li>Confirm catalog <code>contracts</code> version <code>1.7.0</code> (no <code>db:seed</code>)</li><li>Confirm <strong>only</strong> the <code>2026_09_24_020619_…</code> evidence migration ships</li><li><strong>SPA</strong> — Settings soft-gate + guest accept evidence UI + record download actions</li><li><strong>Docs</strong></li><li>Staging smoke below before production traffic</li></ol><p>Suggested merge: <strong>Backend → Frontend → Docs</strong>. Do <strong>not</strong> <code>db:seed</code>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Pest <code>ContractAcceptanceTest</code> green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>2</td><td>Playwright <code>test:e2e:contracts</code> green</td><td>QA</td><td>☐</td></tr><tr><td>3</td><td>Migration <code>2026_09_24_020619_…</code> applied; no empty stub in release</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Catalog <code>contracts</code> version <code>1.7.0</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>SPA deployed <strong>after</strong> migrate</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Staging smoke signed off</td><td>QA / Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → Opportunities, Contracts (free). Optionally install <strong>Storage</strong> before testing file evidence.</li><li>Settings → General → without Storage, signature/ID switches are disabled; enabling via API returns 422. Phone toggle still works.</li><li>Install Storage → enable all three toggles → send contract → public accept incomplete → validation; complete with phone + draw/upload + ID → Active.</li><li>Contract view: phone, IP, Download signature / ID → timeline shows download events.</li><li><strong>Download PDF</strong> shows acceptance block + signature image (not the ID file).</li><li>Soft-delete → files still downloadable after restore; force-delete → signature/ID objects gone.</li><li>Confirm JSON show does <strong>not</strong> expose storage paths.</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (evidence UI disappears; columns remain)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Settings</td><td>Turn all three <code>contracts.acceptance_require_*</code> toggles <strong>off</strong></td></tr><tr><td>Module disable</td><td>Marketplace uninstall Contracts (rows retained)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> drop evidence columns in prod without a data / PII plan</td></tr></tbody></table><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Eng</td><td></td><td></td><td>Go / No-Go</td></tr><tr><td>QA</td><td></td><td></td><td></td></tr><tr><td>Ops</td><td></td><td></td><td></td></tr></tbody></table>',33)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
